// ============================================================================
// MIPI_I3C_apb: APB4 register wrapper around MIPI_I3C_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/MIPI_I3C.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/MIPI_I3C.md
// ============================================================================
module MIPI_I3C_apb #(
  parameter logic [6:0] STATIC_ADDR = 7'h3C,
  parameter logic [47:0] PID = 48'h0123_4567_89AB,
  parameter logic [7:0] BCR = 8'h06,
  parameter logic [7:0] DCR = 8'h5A
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic scl,
  inout wire sda
);
  localparam logic [31:0] ID_VALUE = 32'h4D330200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [7:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd8) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_ibi_req;
  logic [7:0]    c_ibi_data;
  logic [6:0]    c_dyn_addr;
  logic          c_dyn_addr_valid;
  logic          c_irq;
  MIPI_I3C_top #(.STATIC_ADDR(STATIC_ADDR), .PID(PID), .BCR(BCR), .DCR(DCR)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .scl(scl),
    .sda(sda),
    .ibi_req(c_ibi_req),
    .ibi_data(c_ibi_data),
    .dyn_addr(c_dyn_addr),
    .dyn_addr_valid(c_dyn_addr_valid),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [0:0] p_CMD;   // 12'h014 CMD (pulses)
  logic [7:0] r_IBI;   // 12'h018 IBI

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      p_CMD <= '0;
      r_IBI <= 8'h0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      p_CMD <= (wr && hit[5]) ? PWDATA[0:0] & wmask[0:0] : '0;
      if (wr && hit[6]) r_IBI <= (r_IBI & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
    end
  end

  // ---------------- core inputs ----------------
  assign c_ibi_req = p_CMD;
  assign c_ibi_data = r_IBI[7:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd6: apb_rdata = 32'(r_IBI);
      10'd7: apb_rdata = 32'({c_dyn_addr_valid, c_dyn_addr});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
